WITH customer_totals AS (SELECT customer_id, COUNT(CASE WHEN browser = 'Firefox' THEN 1 END) AS firefox_count, MIN(started_at) AS first_started_at FROM sessions WHERE customer_id IS NULL GROUP BY customer_id) SELECT c.country, ct.firefox_count, ct.first_started_at FROM customers c INNER JOIN customer_totals ct ON c.id = ct.customer_id WHERE ct.firefox_count >= 4 ORDER BY first_started_at DESC;
